"""Build only the five Midnight Supper documents from local facts."""
from pathlib import Path
from html import escape
from PIL import Image
import json
ROOT=Path(__file__).resolve().parent
facts=json.loads((ROOT/'facts.json').read_text(encoding='utf-8-sig'))
menus=facts['menus']
phone=facts['phone']; email=facts['email']
phone_label=f'({phone[1:4]}) {phone[4:7]}-{phone[7:]}'
e=escape
routes=[('index','The table'),('menu','The menus'),('gallery','The scenes'),('story','Meet Tricia'),('enquire','Enquire')]
def photo(file,alt,cls='',eager=False):
    w,h=Image.open(ROOT/'img'/file).size
    return f'<img class="{cls}" src="img/{file}" width="{w}" height="{h}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async" style="--native:{w}px">'
def brand():
    return '<a class="brand" href="index.html" aria-label="The Chick Goodies — home">'+photo('brand.webp','The Chick Goodies','',True)+'</a>'
def contact():
    return f'<a href="mailto:{e(email)}">{e(email)}</a><a href="tel:+{phone}">{phone_label}</a>'
def shell(route,title,description,body):
    nav=''.join(f'<a href="{slug}.html"'+(' aria-current="page"' if slug==route else '')+f'><small>0{i+1}</small>{label}</a>' for i,(slug,label) in enumerate(routes))
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | The Chick Goodies</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#151111"><link rel="icon" href="data:,"><link rel="stylesheet" href="midnight.css"><script src="midnight.js" defer></script></head>
<body data-page="{route}"><a class="skip" href="#main">Skip to content</a><header class="masthead">{brand()}<nav aria-label="Main navigation">{nav}</nav><button class="motion" type="button" hidden aria-pressed="false">Motion: on</button></header>
<main id="main" tabindex="-1">{body}</main>
<footer><div class="footer-top"><p class="eyebrow">Your occasion. Her table.</p><a class="closing" href="enquire.html">LET’S MAKE<br><em>AN EVENING.</em><span aria-hidden="true">↗</span></a></div><div class="footer-bottom">{brand()}<div class="contact">{contact()}</div><p>Tomball · The Woodlands<br>Spring · Conroe</p><a href="menu.html">Published menus ↗</a></div><p class="fineprint">Charcuterie Chick · Catering & grazing tables. All enquiries are subject to confirmation; this is not a booking.</p></footer>
</body></html>'''
intro='''<section class="hero spotlight" aria-labelledby="hero-title"><div class="stage-glow" aria-hidden="true"></div><div class="hero-copy"><p class="eyebrow">Tomball, Texas & the surrounding table</p><h1 id="hero-title">GOOD FOOD.<br><em>GREAT</em><br>COMPANY.</h1><div class="hero-bottom"><p>For the moments that deserve<br>more than a meal.</p><a class="round-link" href="menu.html" aria-label="Explore the menus">↗</a></div></div><figure class="hero-still">'''+photo('knot-hero.jpg','A richly arranged grazing table from The Chick Goodies','',True)+'''<figcaption><span>01 / THE GATHERING</span><span>Real food. Real occasions.</span></figcaption></figure><div class="stage-floor" aria-hidden="true">THE EVENING IS YOURS</div><a class="scroll-note" href="#opening">Scroll to set the scene ↓</a></section>
<section class="opening" id="opening"><p class="eyebrow">Act I — A generous beginning</p><h2>A TABLE THAT<br>BRINGS YOU<br><em>CLOSER.</em></h2><div class="opening-copy"><p>Grazing tables, charcuterie carts and scratch-made details. A reason to gather. A little room to linger.</p><p>Tricia brings more than 35 years in restaurants to your occasion — one party at a time.</p><a class="text-link" href="story.html">Meet the woman behind the table <span>↗</span></a></div></section>
<section class="feature-scene reveal"><figure>'''+photo('cart-640.jpg','The Chick Goodies catering cart')+'''<figcaption>THE CART / A DIFFERENT KIND OF CENTREPIECE</figcaption></figure><div><p class="eyebrow">Act II — Choose your scene</p><h2>SMALL BITES.<br><em>BIG ENTRANCE.</em></h2><p>Start with the grazing tables. Add the details that feel like you. Menus, carts, sweets and sips — explore the published options, then talk it through with Tricia.</p><a class="ticket" href="menu.html"><span>Explore the menus</span><span aria-hidden="true">ADMIT ONE ↗</span></a><a class="text-link" href="gallery.html">A look at the real thing ↗</a></div></section>'''
(ROOT/'index.html').write_text(shell('index','Midnight Supper','Discover real grazing tables, charcuterie carts and generous catering by Tricia Holfelder in Tomball, The Woodlands, Spring and Conroe.',intro),encoding='utf-8')
menu_nav=''.join(f'<a href="#{m["id"]}" data-menu="{m["id"]}"><span>0{i+1}</span>{e(m["name"])}</a>' for i,m in enumerate(menus))
images=['knot-hero.jpg','knot-2.jpg','knot-3.jpg','table-01.jpg','wide-640.jpg']
menu_panels=''
for i,m in enumerate(menus):
    menu_panels+=f'''<article class="menu-panel" id="{m['id']}"><div class="menu-photo"><figure>{photo(images[i],'Grazing table inspiration from The Chick Goodies','',i==0)}<figcaption>REAL EVENT PHOTOGRAPH / PRESENTATION INSPIRATION</figcaption></figure><span class="act-number" aria-hidden="true">0{i+1}</span></div><div class="menu-copy"><p class="eyebrow">The grazing collection / 0{i+1}</p><h2>{e(m['name'])}</h2><p class="price">{e(m['price'])}</p><p class="published">Published food price · before setup, extra time & tax</p><p>{e(m['description'])}</p><p class="small">{'Published packages for exactly 75 or 150 guests.' if i==0 else '50-guest minimum.'} 90-minute service.</p><a class="ticket" href="enquire.html?menu={m['id']}"><span>Make this your starting point</span><span aria-hidden="true">↗</span></a></div></article>'''
extras=[('Taco Cart','$26.95'),('Carts','$24.50'),('Slider Menu','$2.95'),('Cakes and Shakes','$9.50'),('Candy Bar Chick','$5.00'),('Zeppole Beignet Chick','$4.50'),('Bloody Mary Chick','$6.50'),('Mimosa Chick','$4.00')]
menu_body='''<section class="page-heading"><p class="eyebrow">The evening / 02</p><h1>SET THE<br><em>TABLE.</em></h1><p>Five ways to graze.<br>One very good place to start.</p></section><section class="menu-theatre" aria-label="Grazing menus"><nav class="menu-selector" aria-label="Choose a grazing menu">'''+menu_nav+'''</nav><div class="menu-stage">'''+menu_panels+'''</div></section><aside class="disclosure"><p class="eyebrow">Before the first bite</p><p>Published table prices include 90 minutes of service. A $229 setup fee and the published 18% tax apply. Extra time is $3 per person per half hour. The tax base is not confirmed; the planner explicitly assumes tax on food, setup and extra time.</p><p>Exact contents, portions, dietary requirements, service details, availability and the final quote must be confirmed with Tricia. Photos show real arrangements, not a guarantee of any particular package.</p></aside><section class="extras"><div><p class="eyebrow">The supporting cast</p><h2>AND A<br><em>LITTLE EXTRA.</em></h2><p>Published prices below. Units, minimums and service details require confirmation; these are not added automatically to your estimate.</p></div><dl>'''+''.join(f'<div><dt>{name}</dt><dd>{price}</dd></div>' for name,price in extras)+'''<div><dt>Easy order boards · Charcuterie Chick board · Apple Pie · Catering Menu</dt><dd>Price on request</dd></div></dl></section>'''
(ROOT/'menu.html').write_text(shell('menu','The Menus','Explore five published grazing menus, from Graze Me, Craze Me to the Holy Grail, plus carts, sweets and sips. Confirm event details with Tricia.',menu_body),encoding='utf-8')
shots=[('knot-4.jpg','A table to gather around','The gathering'),('graze-01.jpg','A closer look at a grazing arrangement','The details'),('table-02.jpg','An event table prepared by The Chick Goodies','The occasion'),('sips-01.jpg','Beverage presentation from The Chick Goodies','The sips'),('board-02.jpg','A charcuterie board from The Chick Goodies','The board'),('sweets-01.jpg','Sweet treats from The Chick Goodies','The sweet finish')]
frames=''.join(f'<figure class="film-frame"><a href="img/{file}" data-lightbox data-caption="{e(caption)}" aria-label="Enlarge: {e(alt)}">{photo(file,alt,"",i<2)}<span class="enlarge" aria-hidden="true">↗</span></a><figcaption><span>FRAME 0{i+1}</span>{caption}</figcaption></figure>' for i,(file,alt,caption) in enumerate(shots))
gallery_body='''<section class="page-heading"><p class="eyebrow">The evening / 03</p><h1>WORTH<br><em>A CLOSER LOOK.</em></h1><p>No stand-ins.<br>Food, tables and details from The Chick Goodies.</p></section><section class="gallery-wrap" aria-label="Real event photo collection"><div class="film-toolbar"><p class="eyebrow">Six frames / a taste of the occasion</p><div class="film-buttons" hidden><button type="button" data-film="-1" aria-label="Previous photographs">←</button><button type="button" data-film="1" aria-label="Next photographs">→</button></div></div><p class="small">Scroll the filmstrip, use the arrows, or open a photograph for a closer look.</p><div class="filmstrip" tabindex="0" aria-label="Photographs, scroll horizontally">'''+frames+'''</div></section><section class="gallery-note"><span class="asterisk" aria-hidden="true">✳</span><h2>YOUR OCCASION.<br><em>ITS OWN CHARACTER.</em></h2><p>These are real arrangements, not a fixed template for your event. Share what catches your eye when you enquire.</p><a class="ticket" href="enquire.html"><span>Tell us what you’re imagining</span><span aria-hidden="true">↗</span></a></section><dialog id="lightbox" aria-labelledby="lightbox-caption"><button type="button" class="close-lightbox" aria-label="Close photograph">Close ×</button><img id="lightbox-image" src="img/knot-4.jpg" width="945" height="720" alt=""><p id="lightbox-caption"></p><p class="small">Use Escape or Close to return to the filmstrip.</p></dialog>'''
(ROOT/'gallery.html').write_text(shell('gallery','The Scenes','See real grazing tables, charcuterie boards, sweet treats and event details from The Chick Goodies. Explore the photographs and plan your occasion.',gallery_body),encoding='utf-8')
story_body='''<section class="story-intro spotlight"><div class="stage-glow" aria-hidden="true"></div><div><p class="eyebrow">The evening / 04 — Tricia Holfelder</p><h1>THE HEART<br><em>OF THE PARTY.</em></h1><p class="lede">A lifetime in hospitality.<br>One occasion at a time.</p></div><figure>'''+photo('tricia-662.jpg','Tricia Holfelder, owner of The Chick Goodies','',True)+'''<figcaption>TRICIA HOLFELDER / THE WOMAN BEHIND THE TABLE</figcaption></figure></section><article class="story-letter"><p class="eyebrow">Meet your host</p><h2>GOOD COMPANY<br>STARTS WITH<br><em>GOOD CARE.</em></h2><div><p>For more than 35 years, Tricia Holfelder has worked both front-of-house and back-of-house in the restaurant industry. That experience sits behind every table she prepares.</p><p>Her approach is personal: one party at a time, with scratch-made breads, jellies and jams. From grazing tables to charcuterie carts, the food is part of the occasion — not an afterthought.</p><p>Based in Tomball and serving The Woodlands, Spring and Conroe, Tricia offers hospitality in English and Spanish.</p><a class="text-link" href="enquire.html">Start a conversation with Tricia ↗</a></div></article><figure class="story-wide reveal">'''+photo('catering-1000.jpg','Catering presentation from The Chick Goodies')+'''<figcaption>FROM THE KITCHEN TO YOUR OCCASION</figcaption></figure><section class="story-end"><p class="eyebrow">From her published story</p><blockquote>“Where Flavor<br>Takes The Lead”</blockquote><p>Charcuterie Chick</p></section>'''
(ROOT/'story.html').write_text(shell('story','Meet Tricia','Meet Tricia Holfelder: more than 35 years of restaurant experience, scratch-made details and personal catering in Tomball and the surrounding area.',story_body),encoding='utf-8')
options=''.join(f'<option value="{m["id"]}">{e(m["name"])} — {e(m["price"])}</option>' for m in menus)
static_rates=''.join(f'<li><strong>{e(m["name"])}</strong>: {e(m["price"])}</li>' for m in menus)
enquire_body='''<section class="page-heading invitation-heading"><p class="eyebrow">The evening / 05</p><h1>YOU BRING<br><em>THE OCCASION.</em></h1><p>We’ll start with the table.<br>An invitation to talk, not a booking.</p></section><section class="invitation"><div class="invitation-top"><span class="eyebrow">An occasion in the making</span><span aria-hidden="true">NO. 005</span></div><div class="planner-layout"><div><h2>LET’S SET<br><em>THE SCENE.</em></h2><p>Choose a starting point to explore published costs. Then write a draft for Tricia to review with you.</p><div class="direct-contact">'''+contact()+'''</div><p class="small">Prefer to talk? Call or email directly. Availability, menu details and all final charges require confirmation.</p></div><form id="planner"><label for="menu-choice">Your starting menu</label><select id="menu-choice" name="menu">'''+options+'''</select><div class="field-pair"><div><label for="guests">Number of guests</label><input id="guests" type="number" min="1" max="10000" step="1" value="75" inputmode="numeric"></div><div><label for="extra-time">Extra service time</label><select id="extra-time"><option value="0">None · 90 minutes included</option><option value="1">30 minutes extra</option><option value="2">60 minutes extra</option><option value="3">90 minutes extra</option><option value="4">120 minutes extra</option></select></div></div><div id="estimate" aria-live="polite" aria-atomic="true"><p>Enable JavaScript for the calculator, or use the published prices below and contact Tricia for a quote.</p></div><p class="small tax-note">Estimate only. Published 18% tax is calculated on food + $229 setup + extra time here. The tax base is not confirmed. Extra time: $3 per person per half hour. Per-person menus: 50 guests minimum. Holy Grail: exactly 75 or 150 guests. No estimate confirms availability or reserves a date.</p><details><summary>View all published food prices</summary><ul>'''+static_rates+'''</ul></details><fieldset><legend>A few details, if you like</legend><p class="small">Optional. Nothing is stored or sent by this website.</p><div class="field-pair"><div><label for="event-date">Event date</label><input id="event-date" type="date"></div><div><label for="occasion">Occasion</label><select id="occasion"><option value="">Choose an occasion</option><option>Wedding</option><option>Private party</option><option>Work gathering</option><option>Other occasion</option></select></div></div><label for="event-notes">Location, dietary needs or ideas</label><textarea id="event-notes" maxlength="1500" rows="3" placeholder="What are you imagining?"></textarea></fieldset><button class="ticket draft-button" type="button" hidden><span>Prepare my enquiry draft</span><span aria-hidden="true">↗</span></button><noscript><p>The draft builder needs JavaScript. Please call or email Tricia using the direct contact links on this page.</p></noscript></form></div><section id="draft-review" hidden aria-labelledby="draft-title"><p class="eyebrow">For your review</p><h2 id="draft-title">YOUR ENQUIRY.<br><em>NOT SENT.</em></h2><label for="draft-text">Review or edit your message</label><textarea id="draft-text" rows="12"></textarea><div class="draft-actions"><button type="button" id="copy-draft">Copy draft</button><a class="ticket" id="open-email" href="mailto:'''+e(email)+'''">Open email app ↗</a></div><p class="small" id="draft-status" aria-live="polite">No message has been sent. Opening your email app creates a draft; you decide whether to send it. You can also copy the text manually.</p></section></section>'''
(ROOT/'enquire.html').write_text(shell('enquire','Your Occasion','Plan an occasion with The Chick Goodies. Explore published grazing-table costs, review estimate assumptions and prepare an enquiry for Tricia.',enquire_body),encoding='utf-8')
print('Built five HTML routes from local facts.json; all brand mounts use img/brand.webp.')
